import { existsSync, readFileSync } from 'node:fs';
import { parse } from 'yaml';
import { z } from 'zod';

// The one body list (district coverage plan 0.3). data/bodies.yaml holds the hand-written
// bodies; data/bodies.districts.yaml is generated by scripts/build-district-catalog.ts, one
// batch at a time, and may not exist yet. Ingest, the seed script and the batch checker all
// read bodies through here, so a district added to the YAML is known everywhere at once.

export const BODY_CATALOG_FILES = ['data/bodies.yaml', 'data/bodies.districts.yaml'] as const;

const slug = z.string().regex(/^[a-z0-9_]+$/);

export const CatalogBodySchema = z.object({
  id: slug,
  name: z.string().min(1),
  type: z.enum(['city_council', 'commissioners_court', 'school_board', 'college_board', 'mud', 'esd', 'water_authority', 'flood_control', 'port', 'metro', 'hcad', 'hoa', 'other']),
  category: z.enum(['tracked', 'ballot_list', 'not_government', 'regional_coming_soon']),
  elected_or_appointed: z.string().min(1),
  impact_rank: z.number().int().nonnegative(),
  sms_eligible: z.boolean(),
  description_en: z.string().min(1),
  description_es: z.string().min(1),
  meeting_info_url: z.string().url(),
  source_url: z.string().url(),
  tax_set_by_body_id: slug.optional(),
  operations_by_body_id: slug.optional(),
  regulated_by: z.string().optional(),
  operator_name: z.string().optional(),
});

export type CatalogBody = z.infer<typeof CatalogBodySchema>;

/** Parse and check one or more YAML texts as a single catalog: unique IDs, resolvable tax links. */
export function parseBodyCatalog(yamlTexts: readonly string[]): CatalogBody[] {
  const rows = yamlTexts.flatMap((text) => z.array(CatalogBodySchema).parse(parse(text) ?? []));
  const ids = new Set<string>();
  for (const row of rows) {
    if (ids.has(row.id)) throw new Error(`duplicate body id: ${row.id}`);
    ids.add(row.id);
  }
  for (const row of rows) {
    if (row.tax_set_by_body_id && !ids.has(row.tax_set_by_body_id)) {
      throw new Error(`body ${row.id}: tax_set_by_body_id ${row.tax_set_by_body_id} is not in the catalog`);
    }
  }
  return rows;
}

export function loadBodyCatalog(files: readonly string[] = BODY_CATALOG_FILES): CatalogBody[] {
  // The first file must exist; later ones are optional (the generated district file starts empty).
  const texts = files
    .filter((path, i) => i === 0 || existsSync(/*turbopackIgnore: true*/ path))
    // The ignore comment stops the bundler tracing the whole project; next.config.ts ships the files.
    .map((path) => readFileSync(/*turbopackIgnore: true*/ path, 'utf8'));
  return parseBodyCatalog(texts);
}

// The HCAD code map has the same split: hand-checked codes in data/hcad-jurisdiction-map.yaml,
// and the generated district codes (scripts/build-district-catalog.ts) beside it.
export const JURISDICTION_MAP_FILES = ['data/hcad-jurisdiction-map.yaml', 'data/hcad-jurisdiction-map.districts.yaml'] as const;

export const JurisdictionMappingSchema = z.object({
  code: z.string().regex(/^[0-9A-Z]{3,6}$/),
  source_name: z.string().min(1),
  body_id: slug,
});

export type JurisdictionMapping = z.infer<typeof JurisdictionMappingSchema>;

/** Parse one or more map files as a single list with no repeated HCAD code. */
export function parseJurisdictionMap(yamlTexts: readonly string[]): JurisdictionMapping[] {
  const rows = yamlTexts.flatMap((text) => z.object({ mappings: z.array(JurisdictionMappingSchema) }).parse(parse(text) ?? { mappings: [] }).mappings);
  const codes = new Set<string>();
  for (const row of rows) {
    if (codes.has(row.code)) throw new Error(`duplicate HCAD code: ${row.code}`);
    codes.add(row.code);
  }
  return rows;
}

export function loadJurisdictionMap(files: readonly string[] = JURISDICTION_MAP_FILES): JurisdictionMapping[] {
  const texts = files
    .filter((path, i) => i === 0 || existsSync(/*turbopackIgnore: true*/ path))
    .map((path) => readFileSync(/*turbopackIgnore: true*/ path, 'utf8'));
  return parseJurisdictionMap(texts);
}
